/* WHICH BANK, BY NAME. Not by the TheaterType enum: that is DESERT=0, JUNGLE=1,
   TEMPERATE=2, WINTER=3 (defines.h:2058) and getting it backwards drew a desert
   map out of the temperate bank -- same slot numbers, different tiles, and the
   atlases are different sizes so even the UVs came out about half right. The pack
   carries its theater as a STRING, which cannot be silently off by one. */
static inline const TtSlot* tt_table(const char* theater, int* n)
{
    if (theater && (theater[0] == 'D' || theater[0] == 'd')) {
        *n = TT_DESERT_N; return TT_DESERT;
    }
    if (theater && (theater[0] == 'W' || theater[0] == 'w')) {
        *n = TT_WINTER_N; return TT_WINTER;
    }
    /* Two letters for the S theaters: SNOW and (in time) SAND share an initial. */
    if (theater && (theater[0] == 'S' || theater[0] == 's') &&
        (theater[1] == 'N' || theater[1] == 'n')) {
        *n = TT_SNOW_N; return TT_SNOW;
    }
    if (theater && (theater[0] == 'S' || theater[0] == 's') &&
        (theater[1] == 'A' || theater[1] == 'a')) {
        *n = TT_SAND_N; return TT_SAND;
    }
    *n = TT_TEMPERAT_N; return TT_TEMPERAT;
}

/* The atlas slot a (template, icon) pair draws from, or -1 if this theater has no
   such tile -- which is a real answer, not an error: the two banks differ. */
static inline int tt_slot_of(const char* theater, int tmpl, int icon, int* sea)
{
    int n = 0;
    const TtSlot* t = tt_table(theater, &n);
    for (int i = 0; i < n; i++)
        if ((int)t[i].tmpl == tmpl && (int)t[i].icon == icon) {
            if (sea) *sea = (int)t[i].sea;
            return (int)t[i].slot;
        }
    if (sea) *sea = 0;
    return -1;
}

/* The atlas rectangle for a slot, in UNPADDED atlas pixels. */
static inline void tt_slot_rect(int slot, float* x0, float* y0)
{
    *x0 = (float)((slot % TT_COLS) * TT_PITCH + TT_GUTTER);
    *y0 = (float)((slot / TT_COLS) * TT_PITCH + TT_GUTTER);
}

